3	import { useState, useRef, useEffect } from 'react'
4	import { cn } from '@/lib/utils'
5	
6	interface MoneyInputProps {
7	  value: number | undefined         // value in cents (integer)
8	  onValueChange: (cents: number | undefined) => void
9	  currency?: string                  // ISO 4217, default: 'USD'
10	  locale?: string                    // default: 'en-US'
11	  placeholder?: string
12	  disabled?: boolean
13	  className?: string
14	}
15	
16	function getCurrencySymbol(currency: string, locale: string): string {
17	  try {
18	    return new Intl.NumberFormat(locale, { style: 'currency', currency, currencyDisplay: 'symbol' })
19	      .formatToParts(0)
20	      .find((p) => p.type === 'currency')?.value ?? currency
21	  } catch {
22	    return currency
23	  }
24	}
25	
26	function centsToDisplay(cents: number | undefined, precision: number): string {
27	  if (cents === undefined) return ''
28	  return (cents / Math.pow(10, precision)).toFixed(precision)
29	}
30	
31	function displayToCents(display: string, precision: number): number | undefined {
32	  const n = parseFloat(display.replace(/,/g, ''))
33	  if (isNaN(n)) return undefined
34	  return Math.round(n * Math.pow(10, precision))
35	}
36	
37	export function MoneyInput({
38	  value,
39	  onValueChange,
40	  currency = 'USD',
41	  locale = 'en-US',
42	  placeholder = '0.00',
43	  disabled = false,
44	  className,
45	}: MoneyInputProps) {
46	  const precision = 2
47	  const symbol = getCurrencySymbol(currency, locale)
48	  const [display, setDisplay] = useState<string>(centsToDisplay(value, precision) ?? '')
49	  const [isFocused, setIsFocused] = useState(false)
50	  const inputRef = useRef<HTMLInputElement>(null)
51	
52	  // Sync display when external value changes (e.g. form reset or record swap)
53	  // Guard: skip update while user is mid-edit to avoid clobbering in-progress input
54	  useEffect(() => {
55	    if (!isFocused) {
56	      setDisplay(centsToDisplay(value, precision) ?? '')
57	    }
58	  }, [value, precision, isFocused])
59	
60	  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
61	    const raw = e.target.value
62	    // Allow only digits, decimal point, minus
63	    if (/^-?\d*\.?\d*$/.test(raw) || raw === '') {
64	      setDisplay(raw)
65	      onValueChange(displayToCents(raw, precision))
66	    }
67	  }
68	
69	  function handleFocus() {
70	    setIsFocused(true)
71	  }
72	
73	  function handleBlur() {
74	    setIsFocused(false)
75	    if (display !== '') {
76	      const cents = displayToCents(display, precision)
77	      if (cents !== undefined) {
78	        setDisplay(centsToDisplay(cents, precision) ?? '')
79	      }
80	    }
81	  }
82	
83	  return (
84	    <div
85	      className={cn(
86	        'flex items-center rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring transition-shadow',
87	        disabled && 'opacity-50 cursor-not-allowed',
88	        className,
89	      )}
90	      onClick={() => inputRef.current?.focus()}
91	    >
92	      {/* Currency symbol prefix */}
93	      <div className="flex items-center px-3 border-r border-input bg-muted/30 rounded-l-md self-stretch">
94	        <span className="text-sm text-muted-foreground tabular-nums select-none">
95	          {symbol}
96	        </span>
97	      </div>
98	
99	      {/* Number input */}
100	      <input
101	        ref={inputRef}
102	        type="text"
103	        inputMode="decimal"
104	        value={display}
105	        onChange={handleChange}
106	        onFocus={handleFocus}
107	        onBlur={handleBlur}
108	        placeholder={placeholder}
109	        disabled={disabled}
110	        className="flex-1 bg-transparent px-3 py-2 text-sm tabular-nums outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed"
111	      />
112	    </div>
113	  )
114	}
