2	import { v5 as uuidv5 } from 'uuid'
3	import type { Json } from '@/lib/supabase/types'
4	import { DEMO_NS, FAKER_SEED } from './constants'
5	
6	export type { Json } from '@/lib/supabase/types'
7	export const asJson = (v: unknown): Json => v as Json
