11	export { faker }
12	
13	// Deterministic uuid from a scope + name, bound to the demo namespace.
14	// Same name always produces the same uuid.
15	export function detId(scope: string, name: string | number): string {
16	  return uuidv5(`${scope}:${String(name)}`, DEMO_NS)
17	}
18	
19	export function resetFaker(): void {
20	  faker.seed(FAKER_SEED)
21	}
22	
23	export function pick<T>(arr: readonly T[]): T {
24	  return arr[Math.floor(faker.number.float({ min: 0, max: arr.length - 0.0001 }))]!
25	}
26	
27	export function weighted<T>(entries: Array<[T, number]>): T {
28	  const total = entries.reduce((a, [, w]) => a + w, 0)
29	  let r = faker.number.float({ min: 0, max: total })
30	  for (const [v, w] of entries) {
31	    r -= w
32	    if (r <= 0) return v
33	  }
34	  return entries[entries.length - 1]![0]
35	}
36	
37	// Random date between two anchors, uniform.
38	export function randDate(start: Date, end: Date): Date {
39	  const t = faker.number.int({ min: start.getTime(), max: end.getTime() })
40	  return new Date(t)
41	}
