// ── FormMoneyInput ─────────────────────────────────────────────────────────────
// Form-compatible variant: shows a dollar input, submits cents via hidden field.
// Drop-in replacement for a plain <Input name="slotPriceCents" /> in uncontrolled forms.

interface FormMoneyInputProps {
  name: string
  defaultCents?: number
  required?: boolean
  disabled?: boolean
  id?: string
  placeholder?: string
}

export function FormMoneyInput({
  name,
  defaultCents = 0,
  required,
  disabled,
  id,
  placeholder,
}: FormMoneyInputProps) {
  const [dollars, setDollars] = useState((defaultCents / 100).toFixed(2))
  const cents = Math.round(parseFloat(dollars || '0') * 100) || 0

  return (
    <div className="relative">
      <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground tabular-nums">
        $
      </span>
      <Input
        type="number"
        inputMode="decimal"
        step="0.01"
        min="0"
        value={dollars}
        onChange={(e) => setDollars(e.target.value)}
        required={required}
        disabled={disabled}
        id={id}
        placeholder={placeholder ?? '0.00'}
        className="pl-7 tabular-nums"
      />
      <input type="hidden" name={name} value={String(cents)} />
    </div>
  )
}

