import type { AdminClient } from '../client'
import type { DemoContext } from '../context'
import { detId } from '../rng'
import { log } from '../log'
import { DEMO_USERS } from '../constants'

export async function seed(sb: AdminClient, ctx: DemoContext): Promise<void> {
  const eventId = detId('flash_event', 'spring-2026')
  const eventDate = new Date()
  eventDate.setDate(eventDate.getDate() + 14)
  const isoDate = eventDate.toISOString().slice(0, 10)

  // 1. Flash event — 1 published
  const { error: eErr } = await sb.from('flash_events').upsert(
    {
      id: eventId,
      studio_id: ctx.studioId,
      artist_id: ctx.artistIds[0]!,
      title: 'Spring Flash Day — Saturday Only',
      slug: 'spring-flash-day-2026',
      description: 'Twelve limited-edition flash designs, booked in 60-minute slots.',
      event_date: isoDate,
      start_time: '11:00',
      end_time: '19:00',
      slot_duration_min: 60,
      slot_price_cents: 25000,
      deposit_cents: 10000,
      currency: 'USD',
      max_slots: 12,
      location_id: ctx.locations.primary,
      public: true,
      status: 'published' as const,
      published_at: new Date(Date.now() - 5 * 86400_000).toISOString(),
      created_by: DEMO_USERS.owner.id,
    },
    { onConflict: 'id' },
  )
  if (eErr) throw new Error(`[flash] flash_events upsert: ${eErr.message}`)
  log.module('flash', 1, 'flash_events')

  // 2. Flash event designs — 8 pieces
  const designs = Array.from({ length: 8 }, (_, i) => ({
    id: detId('flash_design', `${eventId}:${i}`),
    flash_event_id: eventId,
    title: `Design ${String.fromCharCode(65 + i)}`,
    image_url: `https://demo-flash.inkos.test/${eventId}/${i}.png`,
    size_description: `${2 + i}in x ${3 + i}in`,
    placement_options: 'forearm, upper arm, calf',
    price_cents: 25000 + i * 2500,
    display_order: i,
    sold_out: i === 7,
    style_tag_ids: [] as string[],
  }))
  const { error: dErr } = await sb.from('flash_event_designs').upsert(designs, { onConflict: 'id' })
  if (dErr) throw new Error(`[flash] flash_event_designs upsert: ${dErr.message}`)
  log.module('flash', designs.length, 'flash_event_designs')

  // 3. Slots — 12 total, 11am to 7pm hourly
  // Slots at indices 2, 4, 7, 10 are 'booked' — these will get real booking rows below.
  type SlotStatus = 'open' | 'reserved' | 'booked' | 'blocked'
  type Slot = {
    id: string
    flash_event_id: string
    slot_start: string
    slot_end: string
    status: SlotStatus
    design_id: string | null
    booking_id: string | null
    reserved_until: string | null
  }
  const statuses: SlotStatus[] = [
    'open', 'open', 'booked', 'open', 'booked',
    'reserved', 'open', 'booked', 'open', 'open', 'booked', 'open',
  ]
  const bookedSlotIndices = [2, 4, 7, 10]

  // Pre-generate booking IDs for booked slots so we can reference them in the slot rows.
  const bookingIdMap: Record<number, string> = {}
  for (const idx of bookedSlotIndices) {
    bookingIdMap[idx] = detId('flash_booking', `${eventId}:slot:${idx}`)
  }

  const slots: Slot[] = []
  for (let h = 0; h < 12; h++) {
    const slotStart = new Date(`${isoDate}T${String(11 + Math.floor(h / 2)).padStart(2, '0')}:${h % 2 === 0 ? '00' : '30'}:00.000Z`)
    const slotEnd = new Date(slotStart.getTime() + 60 * 60 * 1000)
    slots.push({
      id: detId('flash_slot', `${eventId}:${h}`),
      flash_event_id: eventId,
      slot_start: slotStart.toISOString(),
      slot_end: slotEnd.toISOString(),
      status: statuses[h]!,
      design_id: designs[h % designs.length]!.id,
      booking_id: bookedSlotIndices.includes(h) ? bookingIdMap[h]! : null,
      reserved_until: statuses[h] === 'reserved' ? new Date(Date.now() + 600_000).toISOString() : null,
    })
  }

  // 4. Insert bookings for the 4 booked slots (must exist before slots upsert to satisfy FK).
  // Use demo clientIds in round-robin; fall back gracefully if fewer than 4 clients.
  const artistId = ctx.artistIds[0]!
  const bookingRows = bookedSlotIndices.map((slotIdx, i) => {
    const slot = slots.find((s) => s.id === detId('flash_slot', `${eventId}:${slotIdx}`))!
    const clientId = ctx.clientIds[i % ctx.clientIds.length]!
    return {
      id: bookingIdMap[slotIdx]!,
      studio_id: ctx.studioId,
      client_id: clientId,
      artist_id: artistId,
      scheduled_at: slot.slot_start,
      duration_min: 60,
      status: 'confirmed' as const,
      price_cents: 25000,
      deposit_cents: 10000,
      deposit_paid: true,
      booking_token: detId('flash_booking_token', `${eventId}:slot:${slotIdx}`),
      source: 'public',
      metadata: { flash_event_id: eventId, flash_event_slug: 'spring-flash-day-2026' },
    }
  })

  const { error: bErr } = await sb.from('bookings').upsert(bookingRows, { onConflict: 'id' })
  if (bErr) throw new Error(`[flash] bookings upsert: ${bErr.message}`)
  log.module('flash', bookingRows.length, 'bookings (flash)')

  // 5. Upsert slots (with booking_id populated for booked slots).
  const { error: sErr } = await sb.from('flash_event_slots').upsert(slots, { onConflict: 'id' })
  if (sErr) throw new Error(`[flash] flash_event_slots upsert: ${sErr.message}`)
  log.module('flash', slots.length, 'flash_event_slots')
}

